"""Forward kinematics computed solely from public robot joint geometry."""
import json
import numpy as np
from scipy.spatial.transform import Rotation
s=json.load(open('/app/output/spec.json'))
names=s['action_types']['joint_position']['layout']; axes=np.array(s['proprio']['axis']);origins=np.array(s['proprio']['position_m'])
links=s['links']; parents=dict(zip(links['names'],links['parent']))
joint_links=[n+'_link' for n in names]; joint_idx=dict(zip(joint_links,range(19)))
def transform(q,link):
 chain=[]
 while link is not None:
  if link in joint_idx:chain.append(joint_idx[link])
  link=parents[link]
 T=np.eye(4)
 for i in reversed(chain):
  R=Rotation.from_rotvec(axes[i]*q[i]).as_matrix();A=np.eye(4);A[:3,:3]=R;A[:3,3]=origins[i]-R@origins[i];T=T@A
 return T

def point(q,link,v):
 return (transform(q,link)@np.r_[v,1])[:3]

def points(q):
 return {key:point(q,link,v) for key,link,v in [
 ('lf','left_ankle_link',[.09,.203,-1.065]),('rf','right_ankle_link',[.09,-.203,-1.065]),
 ('lh','left_hand',[.329,.214,.097]),('rh','right_hand',[.329,-.214,.097])]}
def com(q):
 return sum(m*point(q,l,v) for l,m,v in zip(links['names'],links['mass_kg'],links['com_m']))/sum(links['mass_kg'])
if __name__=='__main__':
 from control import get
 p=get();print('g',p[41:]);print('points',points(p[:19]));print('com',com(p[:19]))
PY
